"""Render a Ukrainian report from the preserved experimental evidence."""
from collections import Counter
import json
from pathlib import Path
import re
import subprocess
import yaml

report = Path('reports/lab03')
comparison = report / 'comparisons/cmp-d5d3bf609779'
def read_json(path):
    return json.loads(path.read_text())
manifest = read_json(comparison / 'freeze-manifest.json')
aggregate = read_json(comparison / 'scoring/aggregate.json')
analysis = read_json(report / 'analysis-summary.json')
recommendation = yaml.safe_load((comparison / 'recommendation.yaml').read_text())
regression = yaml.safe_load(next((report / 'regression').glob('*.yaml')).read_text())
schedule = read_json(comparison / 'schedule.json')
family = read_json(comparison / 'revealed-family.json')['family']
calibration = read_json(report / 'calibration/calibration-a/calibration-result.json')
development = read_json(report / 'development/schedule.json')
change = yaml.safe_load(Path('student/lab03/change-declaration.yaml').read_text())
protocol = manifest['protocol']
sections = []
def section(title, body):
    sections.append(f'## {title}\n\n{body.strip()}\n')
def image(name, caption):
    return f'![{caption}](screenshots/{name})\n\nРисунок — {caption} (`{name}`).'
def table(headers, rows):
    return '\n'.join(['| ' + ' | '.join(headers) + ' |', '| ' + ' | '.join(['---'] * len(headers)) + ' |', *['| ' + ' | '.join(str(c).replace('|', '\\|').replace('\n', ' ') for c in row) + ' |' for row in rows]])

section('Ідентифікація подання', '''- URL форку: https://github.com/AntonHritsai/ai-systems-design-course
- Назва особистої гілки: `lab03/anton-hritsai`.
- Студент: `anton-hritsai`; GitHub: `AntonHritsai`.
- Дата виконання: 17.10.2026; часовий пояс відображення — Europe/Kyiv.
- Статус завершення робочого процесу: `complete`.

Повний хеш остаточного коміту міститься в окремому `verification-report.json`, створеному після коміту. Звіт та команди підготовлено за допомогою асистента; семантичні оцінки потребують самостійного перегляду студентом перед захистом. Атрибуція CLI позначає студентський пакет, а не незалежне дослідження кількома оцінювачами.''')
